import{_ as i,a0 as l,w as p,s as d,I as s,x as r,a1 as o,A as a,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"两种方式创建你自己的 Docker 基本映像 | LCTT x X-CMD","titleTemplate":false,"description":"两种方式创建你自己的 Docker 基本映像 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"两种方式创建你自己的 Docker 基本映像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"两种方式创建你自己的 Docker 基本映像 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150330 2 Ways to Create Your Own Docker Base Image","title":"两种方式创建你自己的 Docker 基本映像","tag":"201505","desc":""},"relativePath":"201505/20150330 2 Ways to Create Your Own Docker Base Image.md","filePath":"[post].md"}'),u={name:"201505/20150330 2 Ways to Create Your Own Docker Base Image.md"};function m(c,t,k,b,f,D){const e=l("Link");return p(),d("div",null,[t[18]||(t[18]=s("h1",{id:"两种方式创建你自己的-docker-基本映像",tabindex:"-1"},[r("两种方式创建你自己的 Docker 基本映像 "),s("a",{class:"header-anchor",href:"#两种方式创建你自己的-docker-基本映像","aria-label":"Permalink to “两种方式创建你自己的 Docker 基本映像”"},"​")],-1)),s("p",null,[t[1]||(t[1]=r("欢迎大家，今天我们学习一下 docker 基本映像以及如何构建我们自己的 docker 基本映像。",-1)),o(e,{href:"https://www.docker.com/"},{default:a(()=>[...t[0]||(t[0]=[r("Docker",-1)])]),_:1}),t[2]||(t[2]=r(" 是一个开源项目，提供了一个可以打包、装载和运行任何应用的轻量级容器的开放平台。它没有语言支持、框架和打包系统的限制，从小型的家用电脑到高端服务器，在何时何地都可以运行。这使它们可以不依赖于特定软件栈和供应商，像一块块积木一样部署和扩展网络应用、数据库和后端服务。",-1))]),t[19]||(t[19]=n(`<p>Docker 映像是不可更改的只读层。Docker 使用 <strong>Union File System</strong> 在只读文件系统上增加可读写的文件系统，但所有更改都发生在最顶层的可写层，而其下的只读映像上的原始文件仍然不会改变。由于映像不会改变，也就没有状态。基本映像是没有父类的那些映像。Docker 基本映像主要的好处是它允许我们有一个独立运行的 Linux 操作系统。</p><p>下面是我们如何可以创建自定义的基本映像的方式。</p><h3 id="_1-使用-tar-创建-docker-基本映像" tabindex="-1">1. 使用 Tar 创建 Docker 基本映像 <a class="header-anchor" href="#_1-使用-tar-创建-docker-基本映像" aria-label="Permalink to “1. 使用 Tar 创建 Docker 基本映像”">​</a></h3><p>我们可以使用 tar 构建我们自己的基本映像，我们从一个运行中的 Linux 发行版开始，将其打包为基本映像。这过程可能会有些不同，它取决于我们打算构建的发行版。在 Debian 发行版中，已经预带了 debootstrap。在开始下面的步骤之前，我们需要安装 debootstrap。debootstrap 用来获取构建基本系统需要的包。这里，我们构建基于 Ubuntu 14.04 &quot;Trusty&quot; 的映像。要完成这些，我们需要在终端或者 shell 中运行以下命令。</p><pre><code>$ sudo debootstrap trusty trusty &gt; /dev/null
$ sudo tar -C trusty -c . | sudo docker import - trusty
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/creating-base-image-debootstrap.png" alt="使用debootstrap构建docker基本映像"></p><p>上面的命令为当前文件夹创建了一个 tar 文件并输出到标准输出中，&quot;docker import - trusty&quot; 通过管道从标准输入中获取这个 tar 文件并根据它创建一个名为 trusty 的基本映像。然后，如下所示，我们将运行映像内部的一条测试命令。</p><pre><code>$  docker run trusty cat /etc/lsb-release
</code></pre>`,8)),s("p",null,[o(e,{href:"https://github.com/docker/docker/blob/master/contrib/mkimage-busybox.sh"},{default:a(()=>[...t[3]||(t[3]=[r("Docker GitHub Repo",-1)])]),_:1}),t[4]||(t[4]=r(" 中有一些允许我们快速构建基本映像的事例脚本.",-1))]),t[20]||(t[20]=n(`<h3 id="_2-使用scratch构建基本映像" tabindex="-1">2. 使用Scratch构建基本映像 <a class="header-anchor" href="#_2-使用scratch构建基本映像" aria-label="Permalink to “2. 使用Scratch构建基本映像”">​</a></h3><p>在 Docker registry 中，有一个被称为 Scratch 的使用空 tar 文件构建的特殊库：</p><pre><code>$ tar cv --files-from /dev/null | docker import - scratch
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/creating-base-image-using-scratch.png" alt="使用scratch构建docker基本映像"></p><p>我们可以使用这个映像构建新的小容器：</p><pre><code>FROM scratch
ADD script.sh /usr/local/bin/run.sh
CMD [&quot;/usr/local/bin/run.sh&quot;]
</code></pre><p>上面的 Dockerfile 文件来自一个很小的映像。这里，它首先从一个完全空的文件系统开始，然后它复制新建的 /usr/local/bin/run.sh 为 script.sh ，然后运行脚本 /usr/local/bin/run.sh。</p><h3 id="结尾" tabindex="-1">结尾 <a class="header-anchor" href="#结尾" aria-label="Permalink to “结尾”">​</a></h3><p>这这个教程中，我们学习了如何构建一个开箱即用的自定义 Docker 基本映像。构建一个 docker 基本映像是一个很简单的任务，因为这里有很多已经可用的包和脚本。如果我们想要在里面安装想要的东西，构建 docker 基本映像非常有用。如果有任何疑问，建议或者反馈，请在下面的评论框中写下来。非常感谢！享受吧 😃</p><hr>`,10)),s("p",null,[t[6]||(t[6]=r("via: ",-1)),o(e,{href:"http://linoxide.com/linux-how-to/2-ways-create-docker-base-image/"},{default:a(()=>[...t[5]||(t[5]=[r("http://linoxide.com/linux-how-to/2-ways-create-docker-base-image/",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=r("作者：",-1)),o(e,{href:"http://linoxide.com/author/arunp/"},{default:a(()=>[...t[7]||(t[7]=[r("Arun Pyasi",-1)])]),_:1}),t[11]||(t[11]=r(" 译者：",-1)),o(e,{href:"https://github.com/ictlyh"},{default:a(()=>[...t[8]||(t[8]=[r("ictlyh",-1)])]),_:1}),t[12]||(t[12]=r(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[r("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=r("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[r("LCTT",-1)])]),_:1}),t[16]||(t[16]=r(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[r("Linux中国",-1)])]),_:1}),t[17]||(t[17]=r(" 荣誉推出",-1))])])}const x=i(u,[["render",m]]);export{h as __pageData,x as default};
